});

describe("project.archived", () => {
  it("reports how many issues the cascade took with it", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Cascade",
      slug: "cascade",
      key: "CAS",
      description: null,
