    const seen = capture("project.archived");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: true,
    });

    expect(seen).toHaveLength(1);
    expect(seen[0]?.issuesArchived).toBe(1);
