/**
 * Bulk-import bookkeeping: the `issue_imports` ledger that makes an upload key
 * replayable, and the single transaction that writes a whole batch.
 */
import { and, eq, inArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, parseJsonArray } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

export interface IssueImportRecord {
  readonly orgId: OrgId;
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

/** A row with its assignee already resolved; labels are still names. */
export interface ImportIssueRowValues {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly labels: readonly string[];
  readonly dueAt: IsoTimestamp | null;
}

export interface InsertImportInput {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportIssueRowValues[];
}

/** Bound on `IN (...)` lists so a large batch stays under SQLite's limit. */
const NAME_CHUNK = 400;

function toRecord(row: typeof issueImports.$inferSelect): IssueImportRecord {
  return {
    orgId: brandId<OrgId>(row.orgId),
    importKey: row.importKey,
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toRecord(row) : null;
}

/**
 * Writes the whole batch — missing labels, issues, label links and the ledger
 * row — in one transaction, so a failure leaves nothing behind and the key
 * unused. If the key turns out to be taken already, nothing is written and
 * the existing record is returned with `created: false`.
 */
export async function insertImport(
  input: InsertImportInput,
): Promise<{ readonly created: boolean; readonly record: IssueImportRecord }> {
  const { orgId, projectId } = input;

  return getDb().transaction((tx) => {
    const existing = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (existing) return { created: false, record: toRecord(existing) };

    const stamp = toIsoTimestamp(new Date());

    // Resolve label names against this org only; create the missing ones once.
    const names = [...new Set(input.rows.flatMap((row) => row.labels))];
    const labelIdByName = new Map<string, string>();
    for (let at = 0; at < names.length; at += NAME_CHUNK) {
      const found = tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(
          and(
            orgPredicate(labels.orgId, orgId),
            inArray(labels.name, names.slice(at, at + NAME_CHUNK)),
          ),
        )
        .all();
      for (const label of found) labelIdByName.set(label.name, label.id);
    }
    for (const name of names) {
      if (labelIdByName.has(name)) continue;
      const created = tx
        .insert(labels)
        .values({
          id: newId(),
          orgId,
          name,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning({ id: labels.id })
        .get();
      labelIdByName.set(name, created.id);
    }

    // Archived issues keep their number, so the max is over every row.
    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
      )
      .get();
    let number = highest?.value ?? 0;

    const issueIds: IssueId[] = [];
    for (const row of input.rows) {
      number += 1;
      const id = newId();
      tx.insert(issues)
        .values({
          id,
          orgId,
          projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      const rowLabelIds = [...new Set(row.labels)].map(
        (name) => labelIdByName.get(name) as string,
      );
      if (rowLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            rowLabelIds.map((labelId) => ({ orgId, issueId: id, labelId })),
          )
          .run();
      }

      issueIds.push(brandId<IssueId>(id));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        importKey: input.importKey,
        projectId,
        importedBy: input.authorId,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
      })
      .run();

    return {
      created: true,
      record: { orgId, importKey: input.importKey, projectId, issueIds },
    };
  });
}
