  actor: Actor,''','''/** Token bucket shared by every path that creates issues for an org. */
const ISSUE_CREATE_BUCKET = "issue:create";

/**
 * Tail of the in-flight import per org. Imports of one workspace run one at
 * a time, so two uploads cannot both pass the quota check, and the second of
 * two same-key uploads always sees the first as already imported.
 */
const importQueues = new Map<OrgId, Promise<unknown>>();

/**
 * Bulk import: every row becomes an issue, in file order, or nothing does.
 *
 * Gates run in the same order as `createIssue`. A key the org has already
 * imported short-circuits to the stored result before the quota and the rate
 * allowance are looked at — a replay creates nothing, so it costs nothing.
 * The allowance is spent last, once every other refusal is ruled out, and the
 * batch is then written in a single transaction.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const previous = importQueues.get(input.orgId) ?? Promise.resolve();
  const run = previous.then(
    () => runImport(actor, input),
    () => runImport(actor, input),
  );
  const tail = run.catch(() => undefined);
  importQueues.set(input.orgId, tail);
  void tail.then(() => {
    if (importQueues.get(input.orgId) === tail) importQueues.delete(input.orgId);
  });
  return run;
}

async function runImport(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const earlier = await issueImportRepo.findImport(input.orgId, input.importKey);
  if (earlier) return replayOf(earlier);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
